const $=s=>document.querySelector(s),photo=$('#photo'),wrap=$('#photoWrap'),strip=$('#strip'),dialog=$('#infoDialog'),light=$('#lightbox'),reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
const MATCHES=[{id:'wsl1025',title:'武汉车谷江大女足 vs 浙江杭州银行女足',label:'女超联赛',date:'2026.10.25',cover:'wsl1025-DSC08243'},{id:'fcc0418',title:'FC Cincinnati vs Chicago Fire FC',label:'MLS',date:'2026.04.18',cover:'404A8889'},{id:'fcc0301',title:'FC Cincinnati 2 vs CT United FC',label:'MLS NEXT Pro',date:'2026.03.01',cover:'1E2A0169-2'}];
let current=0,filter='all',activeMatch='wsl1025',ticket=0,animation=null,swipeStart=null,pendingImage=null;
const names={action:'场上交锋',sideline:'人物与场边',stands:'看台与回应',story:'视觉组照'};
const src=p=>p.file;
const visible=()=>PHOTOS.map((p,i)=>({p,i})).filter(({p})=>p.match===activeMatch&&(filter==='all'||(filter==='people'?['sideline','stands'].includes(p.category):p.category===filter)));
const albumPhotos=()=>PHOTOS.filter(p=>p.match===activeMatch);
function number(index){return PHOTOS.filter(p=>p.match===PHOTOS[index].match).findIndex(p=>p.id===PHOTOS[index].id)+1;}
function updateMatch(){const match=MATCHES.find(m=>m.id===activeMatch);$('#matchCompetition').textContent=match.label;$('#matchName').textContent=match.title;$('#matchDate').textContent=match.date;$('.film-size').textContent=albumPhotos().length+' FRAMES';$('.film-note').textContent='每一次快门，都在现场。';}
function renderStrip(){strip.replaceChildren();for(const {p,i}of visible()){const b=document.createElement('button');b.className='thumb';b.dataset.index=i;b.setAttribute('aria-label',`第 ${number(i)} 张：${p.title}`);b.setAttribute('aria-current',String(i===current));const im=document.createElement('img');im.src=p.thumb;im.alt='';im.loading='lazy';im.decoding='async';const n=document.createElement('span');n.textContent=String(number(i)).padStart(2,'0');b.append(im,n);b.onclick=()=>show(i);strip.append(b);}}
function resetZoom(){light.classList.remove('original-size');$('#originalSize').setAttribute('aria-pressed','false');$('#originalSize').textContent='原始尺寸';}
function syncLight(){const p=PHOTOS[current];resetZoom();$('#largePhoto').src=src(p);$('#largePhoto').alt=p.title;$('#lightTitle').textContent=`${p.title} / ${String(number(current)).padStart(2,'0')} — AP1`;$('#originalFile').href=src(p);}
async function show(index,{route=true,direction=1,animate=true}={}){if(index<0||index>=PHOTOS.length)return;const id=++ticket,p=PHOTOS[index];pendingImage?.removeAttribute('src');const img=new Image();pendingImage=img;$('#load').textContent='原图正在载入…';$('#load').hidden=false;try{img.src=src(p);await img.decode();if(id!==ticket)return;current=index;activeMatch=p.match;animation?.cancel();photo.src=img.src;photo.alt=p.title;photo.width=p.width;photo.height=p.height;fitPhoto();$('#title').textContent=p.title;$('#category').textContent=names[p.category];$('#count').textContent=String(number(index)).padStart(2,'0');$('#total').textContent=String(albumPhotos().length).padStart(2,'0');document.title=`${p.title} · AP1 足球摄影`;updateMatch();renderStrip();if(!document.body.classList.contains('exploring'))strip.querySelector('[aria-current=true]')?.scrollIntoView({behavior:reduce?'instant':'smooth',block:'nearest',inline:'nearest'});if(animate&&!reduce)animation=wrap.animate([{transform:`translateX(${direction*18}px) translateZ(-30px) rotateY(${direction*-2}deg)`,opacity:.4},{transform:'none',opacity:1}],{duration:330,easing:'cubic-bezier(.2,.7,.2,1)'});if(route)history.replaceState(null,'','#photo/'+p.id);if(light.open)syncLight();}catch{if(id===ticket)$('#load').textContent='原图载入失败，请重新选择这张作品。';return;}if(id===ticket){$('#load').hidden=true;pendingImage=null;}document.dispatchEvent(new CustomEvent('photochange',{detail:{index:current}}));}
function step(dir){const list=visible();let pos=list.findIndex(x=>x.i===current);if(pos<0)pos=0;const n=list[(pos+dir+list.length)%list.length];if(n)show(n.i,{direction:dir});}
$('#prev').onclick=()=>step(-1);$('#next').onclick=()=>step(1);$('#lightPrev').onclick=()=>step(-1);$('#lightNext').onclick=()=>step(1);
$('#toggleFilm').onclick=()=>{const closed=$('#film').classList.toggle('closed');$('#toggleFilm').setAttribute('aria-expanded',String(!closed));$('#chevron').textContent=closed?'⌃':'⌄';$('#filmContent').inert=closed;$('#filmContent').setAttribute('aria-hidden',String(closed));};
function setFilter(value){filter=value;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===value)));renderStrip();if(!visible().some(x=>x.i===current)&&visible().length)show(visible()[0].i);}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>setFilter(b.dataset.filter));
function pitch(open){$('#pitchPanel').hidden=!open;$('#position').setAttribute('aria-expanded',String(open));}
$('#position').onclick=()=>pitch($('#pitchPanel').hidden);$('#closePitch').onclick=()=>{pitch(false);$('#position').focus();};
function about(){return '<img class="about-brand" src="assets/ap1-full-white.svg" alt="AP1 / AaronPe1 完整署名"><p class="eyebrow">ENGINEERING / FOOTBALL / PHOTOGRAPHY</p><h2>底线以外，<br>比赛之内。</h2><p>我是 Aaron Pei，个人摄影品牌 AP1。<br>工科背景，足球摄影。</p><p>我通常在球场底线、门线与角旗附近拍摄。记录对抗与奔跑，也留意等待、目光，以及比赛结束后人与人之间的回应。</p><a class="contact-link" href="mailto:aaron_pe1@outlook.com">摄影联系 ↗<span>aaron_pe1@outlook.com</span></a><p class="copyright">© '+new Date().getFullYear()+' AP1 / Aaron Pei · 作品版权归摄影师所有</p>';}
function matchArchive(){return '<p class="eyebrow">MATCH ARCHIVE / '+PHOTOS.length+' WORKS</p><h2>每一场，都在现场。</h2><div class="match-archive">'+MATCHES.map(m=>{const p=PHOTOS.find(p=>p.id===m.cover);return '<button class="match-card" data-match="'+m.id+'"><img loading="lazy" src="'+p.thumb+'" alt="'+p.title+'"><strong>'+m.title+' ↗</strong><small>'+m.label+' · '+m.date+' · '+PHOTOS.filter(p=>p.match===m.id).length+' 件作品</small></button>';}).join('')+'</div>';}
document.querySelectorAll('[data-modal]').forEach(b=>b.onclick=()=>{const isAbout=b.dataset.modal==='about';$('#dialogLabel').textContent=isAbout?'AP1 / ABOUT':'AP1 / MATCH ARCHIVE';$('#dialogContent').innerHTML=isAbout?about():matchArchive();if(!isAbout)document.querySelectorAll('[data-match]').forEach(card=>card.onclick=()=>{activeMatch=card.dataset.match;setFilter('all');dialog.close();show(PHOTOS.findIndex(p=>p.id===MATCHES.find(m=>m.id===activeMatch).cover));});dialog.showModal();});
$('#closeDialog').onclick=()=>dialog.close();
function openLight(){syncLight();light.showModal();}$('#inspect').onclick=openLight;$('#closeLight').onclick=()=>light.close();
$('#originalSize').onclick=()=>{const zoom=light.classList.toggle('original-size');$('#originalSize').setAttribute('aria-pressed',String(zoom));$('#originalSize').textContent=zoom?'适合屏幕':'原始尺寸';};
for(const d of [dialog,light])d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});
document.addEventListener('keydown',e=>{if(dialog.open)return;if(document.body.classList.contains('exploring')&&!light.open)return;if(e.key==='Escape'){pitch(false);return;}if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();step(e.key==='ArrowLeft'?-1:1);}});
let suppressClickUntil=0;photo.onclick=()=>{if(Date.now()>suppressClickUntil)openLight();};
wrap.addEventListener('pointerdown',e=>{swipeStart={x:e.clientX,y:e.clientY};});wrap.addEventListener('pointerup',e=>{if(!swipeStart)return;const dx=e.clientX-swipeStart.x,dy=e.clientY-swipeStart.y;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.4){suppressClickUntil=Date.now()+400;step(dx<0?1:-1);}swipeStart=null;});wrap.addEventListener('pointercancel',()=>{swipeStart=null;});
function hashPhoto(){try{const id=decodeURIComponent(location.hash.slice(7));return PHOTOS.findIndex(p=>p.id===id);}catch{return -1;}}window.addEventListener('hashchange',()=>{const i=hashPhoto();if(i>=0)show(i,{route:false});});
$('.brand').onclick=e=>{e.preventDefault();activeMatch='wsl1025';filter='all';setFilter('all');show(0);};
function fitPhoto(){if(document.body.classList.contains('exploring'))return;const box=$('.view-space'),style=getComputedStyle(box),w=box.clientWidth-parseFloat(style.paddingLeft)-parseFloat(style.paddingRight),h=box.clientHeight-parseFloat(style.paddingTop)-parseFloat(style.paddingBottom),p=PHOTOS[current],ratio=p.width/p.height;const width=Math.max(1,Math.min(w,h*ratio));wrap.style.width=width+'px';wrap.style.height=width/ratio+'px';}
new ResizeObserver(fitPhoto).observe($('.view-space'));const initial=hashPhoto();if(initial>=0){current=initial;activeMatch=PHOTOS[initial].match;}updateMatch();renderStrip();show(current,{animate:false});
